  f_planned:=(f_day+time '08:15:30.123456')at time zone 'Europe/Berlin';f_actual:=to_char((f_planned+interval '1 minute 0.111111 second')at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"');
  f_sources:=care_private.basic_care_native_sources(f_t,f_c,f_version,f_measure,f_visit);f_other_sources:=care_private.basic_care_native_sources(f_t,f_c,f_version,f_other_measure,f_other_visit);
  f_native_before:=jsonb_build_object('first',f_sources,'second',f_other_sources);
  f_issue:=jsonb_build_object('schemaVersion','1','requestId',f_issue_req,'tenantId',f_t,'clientId',f_c,'actorId',f_u,'planVersionId',f_version,'measureId',f_measure,'visitId',f_visit,'plannedAt',to_char(f_planned at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'timeZone','Europe/Berlin','secondPersonRequired',false,'reason','Synthetic explicit planning decision without clinical inference','sources',f_sources);
  f_other_issue:=f_issue||jsonb_build_object('requestId',f_other_issue_req,'measureId',f_other_measure,'visitId',f_other_visit,'plannedAt',to_char(((f_day+time '09:15:30.654321')at time zone 'Europe/Berlin')at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'sources',f_other_sources);
  f_prepared:=public.web_prepare_basic_care_binding_intent(f_issue::text,care_private.basic_care_packet_text_hash(f_issue::text));f_committed:=public.web_commit_basic_care_binding_intent(f_t,f_c,f_u,(f_issue->>'requestId')::uuid,care_private.basic_care_packet_text_hash(f_issue::text));SELECT x.original INTO f_issue_receipt FROM care_private.basic_care_binding_requests x WHERE x.request_id=(f_issue->>'requestId')::uuid AND x.auth_user_id=auth.uid();
  IF f_prepared->>'state'IS DISTINCT FROM 'prepared'OR f_committed->>'state'IS DISTINCT FROM 'committed'OR f_issue_receipt->'packet'IS DISTINCT FROM f_issue THEN RAISE EXCEPTION 'Real prepared native binding did not retain exact packet';END IF;
  f_entry:=jsonb_build_object('kind','body_care','title',f_issue_receipt#>'{plan,title}','plannedAt',f_issue_receipt#>'{plan,plannedAt}','occurredAt',null,'planVersionId',f_version,'measureId',f_measure,'visitId',f_visit,'planSnapshotSha256',f_issue_receipt#>'{plan,planSnapshotSha256}',
   'consent','{"state":"not_asked","recordedAt":null,"statedReason":"","consultation":""}'::jsonb,
