  f_performed:=f_entry||jsonb_build_object('occurredAt',f_actual,'consent',jsonb_build_object('state','consented','recordedAt',to_char((f_planned+interval '59 seconds')at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'statedReason','','consultation','Synthetic explicit consent recorded'),'execution',jsonb_build_object('outcome','performed','bodyScope','partial','performedBy',jsonb_build_array(f_u),'interventions',jsonb_build_array('Synthetic actually documented partial body care'),'result','Synthetic individual actual result','deviation',''),'lifecycle','completed');
