  INSERT INTO public.employee_qualifications(id,tenant_id,employee_id,qualification_type,title,issued_at,valid_until,document_id,verified_by,verified_at,status)VALUES(f_qualification,f_t,f_employee,'synthetic_basic_care_review','Synthetic independent BasicCare family qualification',f_day-30,f_day+30,f_document,'Synthetic fixture provisioner',f_planned-interval '1 day','valid');
  INSERT INTO care_private.basic_care_review_scopes(id,tenant_id,employee_id,qualification_id,kind,qualification_fingerprint,document_fingerprint,approved_by,approved_at,valid_until)SELECT f_scope,f_t,f_employee,f_qualification,'basic_care_review',care_private.basic_care_fingerprint(to_jsonb(q)),care_private.basic_care_fingerprint(to_jsonb(d)),f_u,f_planned-interval '1 hour',clock_timestamp()+interval '1 day'FROM public.employee_qualifications q JOIN public.employee_documents d ON d.id=q.document_id WHERE q.id=f_qualification;
  f_review_packet:=jsonb_build_object('schemaVersion','1','action','request','requestId',f_review_req,'tenantId',f_t,'clientId',f_c,'actorId',f_u,'occurredAt',to_char(clock_timestamp()at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'expectedReviewHeadId',null,'expectedReviewRevision',0,'careOriginal',f_receipt->'original','reviewOriginal',null,'reason','Synthetic independent request with actual native source authors','requiredChange','','rationale','');f_review_receipt:=public.web_commit_basic_care_review(f_review_packet);
