  f_control:=jsonb_build_object('prepared',f_prepared,'committed',f_committed,'issuePacket',f_issue,'issueReceipt',f_issue_receipt,'carePacket',f_packet,'careReceipt',f_receipt,'reviewPacket',f_review_packet,'reviewReceipt',f_review_receipt,'decisionPacket',f_decision_packet,'decisionReceipt',f_decision_receipt);PERFORM set_config('request.jwt.claims',f_claims::text,true);
