   f_case_plan:=gen_random_uuid();f_case_version:=gen_random_uuid();f_case_measure:=gen_random_uuid();f_case_visit:=gen_random_uuid();f_case_req:=gen_random_uuid();f_case_review_req:=gen_random_uuid();f_updater:=gen_random_uuid();f_case_ok:=false;
   BEGIN
