     IF(SELECT to_jsonb(p)FROM care_private.basic_care_native_author_proofs p WHERE p.source_kind='care_plan_item'AND p.source_id=f_case_measure)IS DISTINCT FROM f_proof OR f_proof->'native_original'IS NOT DISTINCT FROM(SELECT to_jsonb(i)FROM public.care_plan_items i WHERE i.id=f_case_measure)THEN RAISE EXCEPTION 'Native content edit failed or rewrote old proof';END IF;
    END IF;
    PERFORM set_config('request.jwt.claims',CASE WHEN f_index=3 THEN f_review_claims::text ELSE f_claims::text END,true);
    INSERT INTO public.care_plan_versions(id,tenant_id,care_plan_id,version,snapshot,reason,actor_id,actor_name)SELECT f_case_version,f_t,f_case_plan,1,jsonb_build_object('plan',to_jsonb(p),'items',(SELECT jsonb_agg(to_jsonb(i)ORDER BY i.id)FROM public.care_plan_items i WHERE i.care_plan_id=f_case_plan)),'Synthetic preserved original native author identity',CASE WHEN f_index=1 THEN null WHEN f_index=3 THEN f_reviewer WHEN f_index=9 THEN f_updater ELSE f_u END,'Synthetic original native writer'FROM public.care_plans p WHERE p.id=f_case_plan;
    PERFORM set_config('request.jwt.claims',f_claims::text,true);
    IF f_index IN(5,6)THEN
     IF f_index=5 THEN SELECT to_jsonb(v)INTO f_raw FROM public.care_plan_versions v WHERE v.id=f_case_version;ELSE SELECT to_jsonb(i)INTO f_raw FROM public.care_plan_items i WHERE i.id=f_case_measure;END IF;
     SELECT to_jsonb(p)INTO f_proof FROM care_private.basic_care_native_author_proofs p WHERE p.source_kind=CASE WHEN f_index=5 THEN 'care_plan_version'ELSE 'care_plan_item'END AND p.source_id=CASE WHEN f_index=5 THEN f_case_version ELSE f_case_measure END;
     IF f_raw IS NULL OR f_proof IS NULL THEN RAISE EXCEPTION 'Native/proof absent before actual reincarnation';END IF;f_state_before:=care_private.basic_care_state(f_t,f_c,f_u);
