     ELSE DELETE FROM public.care_plan_items WHERE id=f_case_measure;INSERT INTO public.care_plan_items SELECT(jsonb_populate_record(NULL::public.care_plan_items,f_raw)).*;SELECT to_jsonb(i)INTO f_value FROM public.care_plan_items i WHERE i.id=f_case_measure;END IF;
     IF f_value IS DISTINCT FROM f_raw OR(SELECT to_jsonb(p)FROM care_private.basic_care_native_author_proofs p WHERE p.source_kind=CASE WHEN f_index=5 THEN 'care_plan_version'ELSE 'care_plan_item'END AND p.source_id=CASE WHEN f_index=5 THEN f_case_version ELSE f_case_measure END)IS DISTINCT FROM f_proof OR NOT EXISTS(SELECT 1 FROM care_private.basic_care_native_author_retirements r WHERE r.source_kind=CASE WHEN f_index=5 THEN 'care_plan_version'ELSE 'care_plan_item'END AND r.source_id=CASE WHEN f_index=5 THEN f_case_version ELSE f_case_measure END)THEN RAISE EXCEPTION 'Exact native reincarnation lost success, rewrote proof or inherited old source identity';END IF;
     PERFORM set_config('request.jwt.claims',f_claims::text,true);f_state_after:=care_private.basic_care_state(f_t,f_c,f_u);IF f_state_before IS NOT DISTINCT FROM f_state_after THEN RAISE EXCEPTION 'Whole state token omitted retirement with exact identical native JSON';END IF;
     BEGIN UPDATE care_private.basic_care_native_author_retirements SET retired_at=clock_timestamp()WHERE source_id IN(f_case_version,f_case_measure);RAISE EXCEPTION 'Retirement mutable';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
     BEGIN DELETE FROM care_private.basic_care_native_author_retirements WHERE source_id IN(f_case_version,f_case_measure);RAISE EXCEPTION 'Retirement deletable';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
    END IF;
    IF f_index IN(1,9)AND EXISTS(SELECT 1 FROM care_private.basic_care_native_author_proofs WHERE source_kind='care_plan_version'AND source_id=f_case_version)OR f_index IN(2,10)AND EXISTS(SELECT 1 FROM care_private.basic_care_native_author_proofs WHERE source_kind='care_plan_item'AND source_id=f_case_measure)THEN RAISE EXCEPTION 'Unknown author was silently backfilled';END IF;
    IF f_index=3 AND NOT EXISTS(SELECT 1 FROM care_private.basic_care_native_author_proofs WHERE source_kind='care_plan_version'AND source_id=f_case_version AND actor_profile_id=f_reviewer AND auth_user_id=f_reviewer AND session_id=f_review_s)OR f_index=4 AND NOT EXISTS(SELECT 1 FROM care_private.basic_care_native_author_proofs WHERE source_kind='care_plan_item'AND source_id=f_case_measure AND actor_profile_id=f_reviewer AND auth_user_id=f_reviewer AND session_id=f_review_s)THEN RAISE EXCEPTION 'Native reviewer author did not capture actual own INSERT session';END IF;
