  f_prepared:=public.web_prepare_basic_care_binding_intent(f_case_issue::text,care_private.basic_care_packet_text_hash(f_case_issue::text));f_committed:=public.web_commit_basic_care_binding_intent(f_t,f_c,f_u,(f_case_issue->>'requestId')::uuid,care_private.basic_care_packet_text_hash(f_case_issue::text));SELECT x.original INTO f_case_issue_receipt FROM care_private.basic_care_binding_requests x WHERE x.request_id=(f_case_issue->>'requestId')::uuid AND x.auth_user_id=auth.uid();
  IF f_prepared->>'state'IS DISTINCT FROM 'prepared'OR f_committed->>'state'IS DISTINCT FROM 'committed'OR f_case_issue_receipt->'packet'IS DISTINCT FROM f_case_issue THEN RAISE EXCEPTION 'Real prepared native binding did not retain exact packet';END IF;
